// Lightweight unread counters. Stored per account and browser; no database migration.
const noticeKinds=['news','chat','wish','war'];
const noticeCounts={news:0,chat:0,wish:0,war:0};
let noticePolling=false,noticeAccount='';
const noticeKey=()=> 'wahuelapa-read-v1:'+String(cloud?.user?.id||'guest');
function noticeRead(){try{return JSON.parse(localStorage.getItem(noticeKey())||'{}')||{};}catch{return {};}}
function noticeSave(data){try{localStorage.setItem(noticeKey(),JSON.stringify(data));}catch{}}
function noticeBadge(kind){const count=noticeCounts[kind]||0;return count?'<span class="notice-count" aria-label="'+count+' ungelesen">'+(count>99?'99+':count)+'</span>':'';}
function noticePaint(){for(const kind of noticeKinds){const target=document.querySelector('[data-notice-kind="'+kind+'"]');if(!target||typeof target.querySelector!=='function')continue;target.querySelector('.notice-count')?.remove();if(noticeCounts[kind]&&typeof target.insertAdjacentHTML==='function')target.insertAdjacentHTML('beforeend',noticeBadge(kind));}}
function noticeMark(kind,ids){
 const data=noticeRead();if(!Array.isArray(ids))return;
 if(kind==='news'){data.news=ids;}
 else if(kind==='war'){data.war=ids.slice(0,100);}
 else {data[kind]=Math.max(Number(data[kind]||0),...ids.map(Number).filter(Number.isFinite),0);}
 noticeSave(data);noticeCounts[kind]=0;noticePaint();
}
function noticeRefreshNews(){
 const read=noticeRead(),ids=GAME_NEWS.map(n=>n.date+'|'+n.title);
 // A fresh account sees only the latest announcement, not the entire back catalogue.
 noticeCounts.news=Array.isArray(read.news)?ids.filter(id=>!read.news.includes(id)).length:Math.min(1,ids.length);
 noticePaint();
}
async function noticePoll(){
 if(noticePolling||!cloud?.user||document.hidden)return;
 const account=noticeKey();noticePolling=true;
 try{
  const data=noticeRead();
  const requests=[['chat',()=>cloud.community('chat')],['wish',()=>cloud.community('wish')],['war',()=>cloud.warTimes()]];
  await Promise.all(requests.map(async ([kind,load])=>{
   try{
    const result=await load();if(account!==noticeKey())return;
    const rows=kind==='war'?result:result.items;
    if(!Array.isArray(rows))return;
    const ids=rows.filter(x=>kind==='war'||!x.mine&&!x.deleted).map(x=>kind==='war'?String(x.id):Number(x.id));
    if(kind==='war'){
     if(!Array.isArray(data.war)){data.war=ids.slice(0,100);noticeSave(data);noticeCounts.war=0;}
     else noticeCounts.war=ids.filter(id=>!data.war.includes(id)).length;
    }else{
     const max=Math.max(0,...rows.map(x=>Number(x.id)||0));
     if(!Number.isFinite(Number(data[kind]))){data[kind]=max;noticeSave(data);noticeCounts[kind]=0;}
     else noticeCounts[kind]=ids.filter(id=>id>Number(data[kind])).length;
    }
   }catch{/* Keep the previous unread state during a network error. */}
  }));
  noticePaint();
 }finally{noticePolling=false;}
}
document.addEventListener('community-feed-loaded',e=>{
 const {kind,items}=e.detail||{};if(!['chat','wish'].includes(kind)||!Array.isArray(items))return;
 // The event only fires when the feed was successfully loaded inside its open dialog.
 const max=Math.max(0,...items.map(p=>Number(p.id)||0));
 noticeMark(kind,[max]);
});
setInterval(()=>{if(noticeAccount!==noticeKey()){noticeAccount=noticeKey();noticeCounts.chat=noticeCounts.wish=noticeCounts.war=0;noticeRefreshNews();}void noticePoll();},45000);

