function orb(p,size=''){const imagePath=planetImagePath(p);const level=Object.values(p.buildings||{}).reduce((a,b)=>a+b,0);return `<div class="planet-art asset-planet ${size}" aria-label="${esc(p.kind)} aus dem All"><img src="${imagePath}" alt="${esc(p.name||'Heimatplanet')}" width="768" height="768" decoding="async"><div class="lights" style="opacity:${Math.min(.85,level/40)}"></div></div>`;}
function progress(job,label){const ship=job.workTotal!==undefined,percent=Math.min(100,Math.max(0,ship?100*(1-job.workRemaining/job.workTotal):100*(state.time-job.start)/(job.end-job.start)));return `<div class="job" ${ship?'data-ship-progress':''}><div class="split"><strong>${esc(label)}</strong><span class="muted" data-due="${job.end}">${job.paused?'Pausiert · kein Strom':duration(job.end-state.time)}</span></div><div class="track"><i style="width:${percent}%"></i></div></div>`;}
function shipDuration(info){return info.ratio?duration(Math.ceil(info.ms/info.ratio)):'Pausiert ohne Strom';}
function affordable(p,c){return RES.every(k=>p.resources[k]>=c[k]);}
let productionScope='global';
function tutorialPreferenceKey(){return saveKey()+'-tutorial-'+state.created;}
function tutorialPreference(){try{return JSON.parse(localStorage.getItem(tutorialPreferenceKey())||'{}');}catch{return {};}}
function tutorialGoal(){
 if(tutorialPreference().completed)return null;
 const p=getPlanet(state,'home');
 if(!p.buildings.lab)return ['Forschung beginnen','Baue Forschungslabor Stufe 1.','build'];
 if(!state.tech.scout)return ['Den Horizont erweitern','Erforsche Sensortechnik Stufe 1.','research'];
 if(!p.buildings.shipyard)return ['Bereit zum Aufbruch','Baue Schiffswerft Stufe 1.','build'];
 if(!state.discovered.length)return ['Deine erste Entdeckung','Baue eine Sonde und erkunde einen Planeten.','galaxy'];
 if(!state.tech.colonization)return ['Eine neue Welt','Baue Labor Stufe 2 und erforsche Kolonisierung.','research'];
 if(state.planets.length===1)return ['Die erste Kolonie','Baue ein Kolonieschiff und besiedle dein erkundetes Ziel.','galaxy'];
 if(!state.tech.logistics)return ['Welten verbinden','Erforsche Transporttechnik und baue einen Frachter.','research'];
 // Older saves may have rotated their transport report out of the 60-item log.
 const complete=tutorialPreference().completed||state.reports.some(r=>['Transport angekommen','Material abgeholt','Handelsrunde abgeschlossen','Handelsroute beendet'].includes(r.title))||state.missions.some(m=>m.type==='route'&&m.rounds>0)||state.tech.ramjet>=1;
 return complete?null:['Dein Imperium verbinden','Baue Kolonieminen aus und transportiere Material zwischen deinen Welten.','fleet'];
}
function tutorialBanner(){
 const pref=tutorialPreference(),goal=tutorialGoal();if(pref.dismissed&&!goal)return '';
 if(!goal){if(!pref.completed){try{localStorage.setItem(tutorialPreferenceKey(),JSON.stringify({...pref,completed:true}));}catch{}}
 return `<section class="tutorial-banner completed" aria-label="Tutorial"><span class="tutorial-check" aria-hidden="true">✓</span><div><strong>Tutorial abgeschlossen</strong><small>Die Grundlagen stehen. Entwickle dein Imperium weiter.</small></div>${button('Tutorial beenden','tutorial-dismiss')}</section>`;}
 return `<section class="tutorial-banner" aria-label="Tutorial"><div><span class="eyebrow">DEIN NÄCHSTES ZIEL</span><strong>${goal[0]}</strong><small>${goal[1]}</small></div>${button('Zum nächsten Schritt →','tab',`data-tab="${goal[2]}"`)}</section>`;
}
function productionPanel(p){
 const global=productionScope==='global';
 const rates=global?state.planets.reduce((sum,q)=>{const z=stats(state,q);for(const k of RES)sum[k]+=z.rates[k];return sum;},vector([0,0,0])):stats(state,p).rates;
 const stock=global?state.planets.reduce((sum,q)=>{for(const k of RES)sum[k]+=Number(q.resources?.[k])||0;return sum;},vector([0,0,0])):p.resources;
 return `<section class="panel overview-production"><div class="production-heading"><h2>Produktion pro Stunde</h2><div class="production-switch" role="group" aria-label="Produktionsbereich">${[['global','Global'],['local',p.name]].map(([key,label])=>`<button type="button" data-production-scope="${key}" aria-pressed="${productionScope===key}">${esc(label)}</button>`).join('')}</div></div><p class="fine production-caption">${global?'Gesamtes Imperium · '+state.planets.length+' Welten':esc(p.name)+' · Lokale Produktion'}</p><div class="production-metrics">${RES.map(k=>`<div>${resourceIcon(k)}<div><strong data-production-resource="${k}">${fmt(rates[k])}</strong><small>${LABEL[k]} / Std</small></div></div>`).join('')}</div><div class="production-storage"><h3>${global?'Globale Lagerbestände':'Lokale Lagerbestände'}</h3><div class="production-metrics">${RES.map(k=>`<div>${resourceIcon(k)}<div><strong data-production-stock="${k}">${fmt(stock[k]||0)}</strong><small>${LABEL[k]} gesamt</small></div></div>`).join('')}</div></div><p class="fine">${global?'Summe der aktuellen Förderleistung und Lagerbestände aller Welten.':'Aktuelle Förderleistung und Lagerbestände dieser Welt.'} Strommangel ist berücksichtigt; volle Lager stoppen die Einlagerung.</p></section>`;
}
