function fleetStock(){return fleetOverviewHTML(state.planets,{group:fleetGroup,category:fleetFilter,expanded:fleetExpanded,collapsed:fleetAllCollapsed,mobile:window.matchMedia?.('(max-width:600px)').matches||false});}
function fleetWorld(id){return state.planets.find(p=>p.id===id)||TARGETS.find(p=>p.id===id)||galaxyData?.planets?.find(p=>p.id===id)||cloud?.pvp?.social?.partners?.flatMap(p=>p.planets||[]).find(p=>p.id===id)||{id,name:id||'Unbekannte Welt'};}
function fleetMissions(missions){return '<div class="route-cards">'+missions.map(m=>{
 if(m.type==='route')return routeCard(m,false);
 const returning=m.phase==='return',f=fleetManifest(m),progress=fleetMissionProgress(m,state.time);
 return fleetTravelCard({title:({station:'Stationieren',salvage:'Trümmerbergung',collect:'Abholen',deliver:'Lieferung',transport:'Lieferung',probe:'Erkundung',colony:'Kolonisierung'})[m.type]||'Flottenauftrag',status:m.awaitingUnload?'Wartet auf Lagerplatz · Schiffe gebunden':returning?'Rückflug':'Unterwegs',worlds:(returning?[m.to,m.from]:[m.from,m.to]).map(fleetWorld),fleet:f,cargoHTML:costHTML(m.cargo),capacity:fleetCapacity(state,f),info:m.type==='salvage'&&!returning?'Trümmer werden bei Ankunft bis zum verfügbaren Laderaum geborgen.':m.type==='collect'&&!returning?'Material wird am Ziel abgeholt.':m.type==='colony'?'Das Kolonieschiff gründet am Ziel eine neue Kolonie.':'',due:progress.end,start:progress.start,now:state.time,waiting:!!m.awaitingUnload,clock:m.awaitingUnload?'Restladung bleibt an Bord':duration(m.due-state.time)});
 }).join('')+'</div>'+(missions.length?'':'<p class="muted">Keine lokalen Flotten unterwegs.</p>');}
app.addEventListener('click',e=>{
 const b=e.target.closest('[data-action="fleet-group"], [data-action="fleet-filter"], [data-action="fleet-collapse-all"]');
 if(!b)return;
 if(b.dataset.action==='fleet-collapse-all'){
  // Collapse every card without dispatching a game command or changing the filters.
  // Clear old expansion choices from other groups/filters, too.
  fleetAllCollapsed=true;
  fleetExpanded.clear();
  for(const el of app.querySelectorAll('.fleet-overview [data-fleet-detail]')){
   el.open=false;
   fleetExpanded.set(el.dataset.fleetDetail,false);
  }
  return;
 }
 captureFleetOverview();
 if(b.dataset.action==='fleet-group')fleetGroup=b.dataset.value;else fleetFilter=b.dataset.value;
 render();
 document.querySelector(`[data-action="${b.dataset.action}"][data-value="${b.dataset.value}"]`)?.focus();
});

function fleetMenu(){fleetLastSection[fleetGroupFor(fleetSection)]=fleetSection;return '<div class="fleet-page-title"><h1>Flotten</h1></div>'+fleetNavigation(fleetSection,{routes:state.missions.filter(m=>m.type==='route').length,incoming:cloud?.pvp?.incoming?.length||0});}
function selectFleetSection(section,focus=false){if(!Object.hasOwn(FLEET_LABELS,section))return;tab='fleet';fleetSection=section;render();if(focus)document.getElementById('fleet-tab-'+section)?.focus();if(['pvp','defense'].includes(section)){void refreshGalaxy(true);void refreshReports();}if(section==='reports'){reportFilters.mission=null;void refreshReports();}}

function fleetPane(key){return `<div class="fleet-pane" role="region" id="fleet-pane-${key}" aria-labelledby="fleet-tab-${key}" ${fleetSection!==key?'hidden':''}>`;}
function fleet(p){
 if(fleetSection==='partners')return fleetMenu()+fleetPane('partners')+socialView(state,cloud?.pvp?.social,{busy:readOnly||cloudBlocked||galaxyBusy||cloudSaving,now:gameNow(),mode:socialMode,to:socialTarget})+'</div>';

 if(fleetSection==='reports')return fleetMenu()+fleetPane('reports')+reportsPage(reportData,{...reportFilters,...reportFormDraft},state,galaxyData,{busy:reportBusy,error:reportError,selected:reportSelected,opened:reportOpened,durable:reportDurable})+'</div>';
 if(['pvp','defense'].includes(fleetSection))return fleetMenu()+fleetPane(fleetSection)+pvpView(state,cloud?.pvp,galaxyData,readOnly||cloudBlocked||galaxyBusy||cloudSaving,pvpDraft,{now:gameNow(),reports:reportCache,opened:reportOpened,section:fleetSection})+'</div>';
 if(fleetSection==='orders'&&['support','partner-deliver'].includes(orderMode))return fleetMenu()+fleetPane('orders')+orderNavigation()+socialView(state,cloud?.pvp?.social,{busy:readOnly||cloudBlocked||galaxyBusy||cloudSaving,mode:orderMode==='support'?'support':'deliver',to:socialTarget,ordersOnly:true})+'</div>';
 if(fleetSection==='repair')return fleetMenu()+fleetPane('repair')+repairDockView(state,p,{busy:readOnly||cloudBlocked||galaxyBusy||cloudSaving,ready:!cloud?.authoritative||!!cloud.pvp?.features?.repairDock,key:repairSelectedKey,scope:repairDraftKey(p,''),drafts:Object.fromEntries(Object.keys(SHIPS).map(k=>[k,repairDrafts.get(repairDraftKey(p,k))]))})+'</div>';
 if(fleetSection==='orbital')return fleetMenu()+fleetPane('orbital')+orbitalYardView(p)+'</div>';
 const head=shipyardView(p);
 return fleetMenu()+fleetPane('hangar')+head+`
 <section class="panel"><h2>Hangar & Flotten im Orbit · ${esc(p.name)}</h2><div class="chips">${Object.entries(SHIPS).map(([k,sh])=>`<span>${unitIcon(k)} ${orbitCondition(p,k).total} × ${sh.name}</span>`).join('')}</div>${Object.keys(SHIPS).filter(k=>orbitCondition(p,k).damaged).map(k=>'<div class="hangar-damage"><strong>'+unitIcon(k)+' '+SHIPS[k].name+'</strong>'+orbitConditionHTML(p,k)+'</div>').join('')}<p class="fine">Schiffe im Dock sind für Flüge gesperrt. Unterwegs gebundene Schiffe erscheinen in der Gesamtübersicht.</p></section>
 </div>${fleetPane('orders')}${fleetOrderEditor(p)}
 <section class="panel"><h2>Lokale Materialreserve</h2><p class="fine">Diese Mengen bleiben bei Flottenbeladung auf ${esc(p.name)}. Bau und Forschung dürfen sie verwenden.</p><form id="reserve-form" data-planet="${p.id}"><div class="form-grid">${RES.map(k=>`<label>${LABEL[k]}<input name="${k}" type="number" min="0" max="1000000000000" step="1" value="${p.reserves?.[k]||0}" required></label>`).join('')}</div><button ${readOnly?'disabled':''}>Reserven speichern</button></form></section>
 </div>${fleetPane('routes')}${tradeRoutes(p)}
 </div>${fleetPane('overview')}<section class="panel fleet-overview">${fleetStock()}<h3 class="fleet-underway-heading">Unterwegs · ${state.missions.length}</h3>${fleetMissions(state.missions)}${galaxyMissionsHTML()}${fleetExternalMissions()}</section>`+fleetReports()+'</div>';
}
function updateRepairQuote(){
 if(!state)return;const busy=readOnly||cloudBlocked||galaxyBusy||cloudSaving;for(const f of document.querySelectorAll('[data-repair-form]')){const p=getPlanet(state,f.dataset.planet);updateRepairCard(f,p,stats(state,p).ratio,{busy,full:repairOrders(p).length>=20});}
}
document.addEventListener('click',e=>{
 const b=e.target.closest('[data-action="repair-open"],[data-action="repair-build"],[data-action="cancel-repair"],[data-action="resume-repair"],[data-repair-set]');if(!b||b.disabled)return;
 if(b.dataset.repairSet!==undefined){if(readOnly||cloudBlocked||galaxyBusy||cloudSaving)return;const f=b.closest('form'),input=f.elements.namedItem('count');input.value=b.dataset.repairSet==='max'?f.querySelector('[data-repair-range]').max:0;input.dispatchEvent(new Event('input',{bubbles:true}));return;}
 if(['cancel-repair','resume-repair'].includes(b.dataset.action)){void command({type:b.dataset.action,id:Number(b.dataset.id),planet:b.dataset.planet});return;}
 if(b.dataset.planet)state.active=b.dataset.planet;repairSelectedKey=b.dataset.key||'';
 if(b.dataset.action==='repair-build'){tab='build';render();}else selectFleetSection('repair');persist();window.scrollTo({top:0,behavior:'smooth'});
});
function repairPlanInput(e){const form=e.target.closest('[data-repair-form]');if(!form)return;if(e.target.matches('[data-repair-range]'))form.elements.namedItem('count').value=e.target.value;captureRepairDrafts();updateRepairQuote();refreshScrapCards();}
document.addEventListener('input',repairPlanInput);document.addEventListener('change',repairPlanInput);
document.addEventListener('submit',e=>{const f=e.target;if(!f.matches?.('[data-repair-form]'))return;e.preventDefault();updateRepairQuote();if(f.querySelector('[type=submit]').disabled)return;void command({type:'repair',planet:f.dataset.planet,key:f.elements.namedItem('key').value,count:Number(f.elements.namedItem('count').value)});});

function fleetDraftKey(planet){return `${cloud?.user?.id||'guest'}:${planet}`;}
function captureFleetDraft(){for(const id of ['fleet-order-form','route-form','reserve-form','social-flight-form','social-invite-form']){const form=document.getElementById(id);if(!form)continue;const key=fleetDraftKey(form.dataset.planet)+(id==='route-form'?':route:'+form.dataset.routeId:id==='social-flight-form'?':social:'+form.dataset.op:''),draft=fleetDrafts.get(key)||{};draft[id]={fields:[...form.elements].filter(el=>el.name).map(el=>({name:el.name,value:el.value,checked:el.checked})),stops:id==='route-form'?readRouteStops(form):null};fleetDrafts.set(key,draft);}}
function restoreFleetDraft(){for(const id of ['fleet-order-form','route-form','reserve-form','social-flight-form','social-invite-form']){const form=document.getElementById(id);if(!form)continue;const key=fleetDraftKey(form.dataset.planet)+(id==='route-form'?':route:'+form.dataset.routeId:id==='social-flight-form'?':social:'+form.dataset.op:''),saved=fleetDrafts.get(key)?.[id];if(!saved)continue;if(saved.stops)form.querySelector('#route-stops').innerHTML=saved.stops.map((stop,i)=>routeStopRow(stop.planet,i===0,stop)).join('');const seen={};for(const field of saved.fields){const i=seen[field.name]||0;seen[field.name]=i+1;const el=form.querySelectorAll(`[name="${field.name}"]`)[i];if(el){el.value=field.value;if(el.type==='checkbox')el.checked=field.checked;}}}}
function orderValue(v){const x=String(v).trim().toLowerCase();return x==='max'?'max':x!==''?Number(x):NaN;}
function readRouteStops(form){return [...form.querySelectorAll('.route-stop')].map(row=>{const mode=row.querySelector('[name="stop-mode"]')?.value||'both';return {planet:row.querySelector('[name="stop-planet"]').value,load:Object.fromEntries(RES.map(k=>[k,mode==='unload'?0:orderValue(row.querySelector(`[name="load-${k}"]`).value)])),unload:Object.fromEntries(RES.map(k=>[k,mode==='load'?0:orderValue(row.querySelector(`[name="unload-${k}"]`).value)]))};});}
function routePauseButton(m){return cloud?.authoritative&&!cloud.pvp?.features?.routePause?'':button(m.paused?'Fortsetzen':m.pauseRequested?'Pause verwerfen':'Am Startplaneten pausieren',m.paused?'resume-route':m.pauseRequested?'cancel-route-pause':'pause-route',`data-id="${m.id}"`,readOnly||m.stopping||m.awaitingUnload);}


function renderOrderFlightPreview(form,flight,data){
 const output=document.getElementById('fleet-estimate');if(!output)return;
 const capacity=Math.max(0,flight.capacity),type=data.get('type');
 const from=getPlanet(state,form.dataset.planet||state.active),to=getPlanet(state,data.get('to'));
 const cargo=Object.fromEntries(RES.map(k=>[k,Math.max(0,Number(orderValue(data.get(k)))||0)]));
 const isMax=RES.some(k=>orderValue(data.get(k))==='max');
 const used=RES.reduce((sum,k)=>sum+cargo[k],0);
 const fleet=readMixedFleet(form),count=Object.values(fleet).reduce((sum,n)=>sum+n,0);
 const manifest=RES.map(k=>'<span>'+resourceIcon(k)+' '+LABEL[k]+': <strong>'+(orderValue(data.get(k))==='max'?'MAX':fmt(cargo[k]))+'</strong></span>').join('');
 const usedLabel=isMax?'MAX (bei Start berechnet)':fmt(used);
 output.innerHTML='<div class="order-preview-title">✦ Flugvorschau</div>'
 +'<div class="order-preview-grid"><span>Startplanet</span><strong>'+esc(from.name)+'</strong>'
 +'<span>Zielplanet</span><strong>'+esc(to.name)+'</strong>'
 +'<span>Flotte</span><strong>'+fmt(count)+' Schiffe</strong>'
 +'<span>Laderaum (belegt / gesamt)</span><strong>'+usedLabel+' / '+fmt(capacity)+'</strong>'
 +'<span>Noch verfügbar</span><strong>'+(isMax?'Wird berechnet':fmt(Math.max(0,capacity-used)))+'</strong>'
 +'<span>Flugzeit je Strecke</span><strong>'+duration(flight.ms)+'</strong>'
 +'<span>Treibstoff gesamt</span><strong>'+fmt(flight.fuel*(type==='station'?1:2))+'</strong>'
 +'<span>Langsamstes Schiff</span><strong>'+esc(SHIPS[flight.slowest].name)+'</strong></div>'
 +'<div class="order-preview-manifest"><span>Geladene Rohstoffe'+(type==='collect'?' (Abholung)':'')+'</span><div>'+manifest+'</div></div>';
}

function fleetEstimates(){
 if(!state)return;refreshCargoHangars();const p=getPlanet(state,state.active),form=document.getElementById('fleet-order-form');
 if(form){const d=new FormData(form),to=state.planets.find(q=>q.id===d.get('to'));try{const fleet=readMixedFleet(form);fleetDispatchAction({type:d.get('type'),fleet});for(const [key,count] of Object.entries(fleet))if(count>(p.ships[key]||0))throw Error(`${SHIPS[key].name}: ${count} gewählt, nur ${p.ships[key]||0} verfügbar. Bitte die Auswahl anpassen.`);if(d.get('type')==='salvage'&&!RES.some(k=>(ownDebris(to?.id)[k]||0)>0))throw Error('An diesem Ziel liegen keine Trümmer.');const f=fleetLegInfo(state,p,to,fleet);renderOrderFlightPreview(form,f,d);form.querySelector('button[type="submit"]').disabled=readOnly||cloudBlocked;}catch(e){document.getElementById('fleet-estimate').textContent=e.message;form.querySelector('button[type="submit"]').disabled=true;}}

 const route=document.getElementById('route-form');if(route){const output=document.getElementById('route-estimate'),submit=route.querySelector('[type=submit]');try{const fleet=checkedFleet(readMixedFleet(route)),stops=readRouteStops(route),home=getPlanet(state,route.dataset.planet);if(stops.length<2||stops.some((q,i)=>q.planet===stops[(i+1)%stops.length].planet))throw Error('Mindestens zwei Stopps, keine direkt aufeinanderfolgenden gleichen Planeten.');const f=routeInfo(state,stops,fleet),editingRoute=state.missions.find(m=>m.type==='route'&&m.id===Number(route.dataset.routeId)),bound=editingRoute?fleetManifest(editingRoute):{},missing=Object.entries(fleet).some(([k,n])=>(home.ships[k]||0)+(bound[k]||0)<n),editing=!!editingRoute;output.innerHTML=`<div class="trade-metrics"><span><strong>${Object.values(fleet).reduce((a,b)=>a+b,0)}</strong> Schiffe</span><span><strong>${fmt(f.capacity)}</strong> Laderaum</span><span><strong>${duration(f.ms)}</strong> je Runde</span><span><strong>${f.fuel}</strong> Treibstoff / Runde</span></div><p class="fine">${SHIPS[f.slowest].name} bestimmt das Flottentempo. Forschungsboni und Sparflug sind berücksichtigt.</p>${missing?`<p class="${editing?'pending-change':'requirement'}">${editing&&!editingRoute.paused?'Verfügbarkeit wird bei Rückkehr geprüft. Fehlen Schiffe, bleibt die bisherige Route aktiv.':'Nicht genügend freie oder auf dieser Route gebundene Schiffe am Startplanet.'}</p>`:''}`;submit.disabled=readOnly||cloudBlocked||galaxyBusy||cloudSaving||(missing&&(!editing||editingRoute.paused));for(const row of route.querySelectorAll('.route-stop')){const q=getPlanet(state,row.querySelector('[name=stop-planet]').value);row.querySelector('summary').innerHTML=`${orb(q,'small')}<strong>${esc(q.name)}</strong><span>Bearbeiten</span>`;for(const k of RES)row.querySelector(`[data-stock="${k}"]`).textContent=fmt(q.resources[k]+q.depot[k]);}}catch(e){output.textContent=e.message;submit.disabled=true;}}

}
app.addEventListener('submit',e=>{if(!['fleet-order-form','route-form','reserve-form'].includes(e.target.id))return;e.preventDefault();const f=new FormData(e.target);if(e.target.id==='reserve-form')command({type:'reserve',reserves:Object.fromEntries(RES.map(k=>[k,Number(f.get(k))]))});else if(e.target.id==='route-form')command({type:Number(e.target.dataset.routeId)?'edit-route':'route',id:Number(e.target.dataset.routeId),planet:e.target.dataset.planet,name:f.get('name'),fleet:readMixedFleet(e.target),repeat:f.get('repeat')==='true',stops:readRouteStops(e.target)});else command({type:f.get('type'),planet:e.target.dataset.planet,fleet:readMixedFleet(e.target),to:f.get('to'),order:Object.fromEntries(RES.map(k=>[k,f.get('type')==='salvage'?0:orderValue(f.get(k))]))});});
