 const cargo=Object.fromEntries(RES.map(k=>[k,Number(d.get('cargo-'+k)||0)])),payment=Object.fromEntries(RES.map(k=>[k,Number(d.get('payment-'+k)||0)])),cap=fleetCapacity(state,fleet);if([...Object.values(cargo),...Object.values(payment)].some(n=>!Number.isSafeInteger(n)||n<0))throw Error('Wähle ganze, positive Rohstoffmengen.');if(Object.values(cargo).reduce((a,b)=>a+b,0)>cap||Object.values(payment).reduce((a,b)=>a+b,0)>cap)throw Error('Die Ladung überschreitet den Laderaum.');if(RES.some(k=>from.resources[k]<(cargo[k]+(k==='fuel'?fuel:0))))throw Error('Rohstoffe oder Treibstoff für Hin- und Rückflug reichen nicht.');if(form.dataset.op!=='support'&&!Object.values(cargo).some(n=>n>0))throw Error('Wähle eine positive Lieferung.');if(form.dataset.op==='trade-offer'&&!Object.values(payment).some(n=>n>0))throw Error('Wähle eine positive Gegenleistung.');output.textContent=from.name+' → '+to.name+' · Je Strecke '+duration(ms)+' · Hin- und Rückflug: '+fuel.toLocaleString('de-DE')+' Treibstoff. '+SHIPS[slowest].name+' bestimmt das Tempo.';output.classList.remove('requirement');submit.disabled=readOnly||cloudBlocked||galaxyBusy||cloudSaving;
