 if(next==='max'&&!route){const key=RES.find(k=>input.name.endsWith(k)),p=getPlanet(state,state.active);let room=cap;const prefix=input.name.slice(0,-key.length);for(const k of RES)if(k!==key){const other=form.elements.namedItem(prefix+k);if(other)room-=Number(other.value)||0;}next=Math.max(0,room);if(form.id==='social-flight-form'&&prefix==='cargo-'){const to=cloud?.pvp?.social?.partners.flatMap(q=>q.planets).find(q=>q.id===form.elements.namedItem('to').value),voyageFuel=to?Object.entries(readMixedFleet(form)).reduce((n,[ship,count])=>n+2*sharedFlight(state,p,to,count,ship).fuel,0):0;next=Math.min(next,Math.floor(Math.max(0,p.resources[key]-(p.reserves?.[key]||0)-(key==='fuel'?voyageFuel:0))));}else if(form.id==='fleet-order-form')next='max';}
